) as v(category, name, description, lat, lng, country, source, sort_order, image_url, translations)
where not exists (
  select 1 from public.points_of_interest p
  where p.country = v.country
    and abs(p.lat - v.lat) < 0.0015
    and abs(p.lng - v.lng) < 0.0025
    and (lower(p.name) = lower(v.name)
         or (abs(p.lat - v.lat) < 0.0006 and abs(p.lng - v.lng) < 0.0010))
);
